}

int main(int argc, char **argv) {
  // unbuffer
  setbuf(stdin, NULL);
  setbuf(stdout, NULL);

  if (argc < 2) {
    std::cout << "Usage: " << argv[0] << " <rom file>" << std::endl;
    return 1;
  }

  Machine_State state;
  // load rom:
  FILE *fd = fopen(argv[1], "r");
  if (!fd) {
    perror("Open:");
    return 1;
  }
  if (fread(state.rom.data(), 1, state.rom.size(), fd) != state.rom.size()) {
    perror("Read:");
    return 1;
  }

  // emulate
  while (true) {
    tick(state);
  }
}

