from intel4004 import decode

# Load the binary file
def load_binary(file_path):
    try:
        with open(file_path, "rb") as f:
            return f.read()
    except Exception as e:
        print(f"Error reading binary file: {e}")
        return None

# Decode instructions
binary_path = "/home/ctfplayer/ctf_files/chal.rom"
data = load_binary(binary_path)
if data:
    decoded_instructions = decode(data)
    for inst in decoded_instructions:
        print(inst)

